session_module:
import {normalize, analyze} from './analysis.mjs';

const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const text = value => typeof value === 'string' && value.trim().length > 0 && value.length <= 2000;
const invalid = () => { throw new Error('이어보기 파일의 내용이 맞지 않아요. 저장한 Avatar 작업 파일을 골라주세요.'); };

function readAnalysis(value, choiceIds) {
  if (value === null) return null;
  if (!object(value) || !['headline', 'summary', 'next_question'].every(key => text(value[key]))
      || !Array.isArray(value.selected_ids) || !value.selected_ids.length
      || value.selected_ids.length > 60 || new Set(value.selected_ids).size !== value.selected_ids.length
      || !value.selected_ids.every(id => typeof id === 'string' && !/[\r\n]/.test(id) && choiceIds.has(id))
      || typeof value.analyzed_at !== 'string' || value.analyzed_at.length > 100
      || /[\r\n]/.test(value.analyzed_at) || !Array.isArray(value.limitations)
      || value.limitations.length > 5 || !value.limitations.every(text)
      || !Array.isArray(value.insights) || value.insights.length > 3) invalid();
  const selected = new Set(value.selected_ids);
  const insights = value.insights.map(item => {
    if (!object(item) || !['title', 'interpretation', 'alternative'].every(key => text(item[key]))
        || !Array.isArray(item.evidence_ids) || !item.evidence_ids.length
        || item.evidence_ids.length > 20 || !item.evidence_ids.every(id => selected.has(id))) invalid();
    return {title: item.title, interpretation: item.interpretation, alternative: item.alternative,
      evidence_ids: [...item.evidence_ids]};
  });
  return {headline: value.headline, summary: value.summary, next_question: value.next_question,
    limitations: [...value.limitations], insights, selected_ids: [...value.selected_ids],
    analyzed_at: value.analyzed_at};
}

export function restoreSession(input) {
  if (!object(input) || input.format !== 'avatar-session/1'
      || !['demo', 'records'].includes(input.source) || !object(input.feedback)) invalid();
  const data = normalize(input.records);
  const result = analyze(data);
  const aiResult = readAnalysis(input.analysis, new Set(data.choices.map(choice => choice.id)));
  const allowed = new Set(result.recurring.map(group => group.criterion.ref));
  if (aiResult) allowed.add('ai');
  const feedback = Object.fromEntries(Object.entries(input.feedback).map(([key, value]) => {
    if (!allowed.has(key) || typeof value !== 'string' || value.length > 3000) invalid();
    return [key, value];
  }));
  return {data, result, feedback, aiResult, mode: 'session'};
}

export function sessionText(data, mode, feedback, aiResult) {
  const value = {format: 'avatar-session/1', source: mode === 'demo' ? 'demo' : 'records',
    saved_at: new Date().toISOString(), records: data, feedback, analysis: aiResult};
  const verified = restoreSession(value);
  value.records = verified.data;
  value.feedback = verified.feedback;
  value.analysis = verified.aiResult;
  const output = JSON.stringify(value);
  if (new TextEncoder().encode(output).length > 8 * 1024 * 1024)
    throw new Error('이어보기 파일이 8MB를 넘어요. 더 적은 기록을 가져와 다시 저장해주세요.');
  return output;
}

report_label:
